float sdcircle(in vec2 p, in float r)
{
    return length(p) - r;
}

float sdTriangle( in vec2 p, in vec2 q )
{
    p.x = abs(p.x);
    vec2 a = p - q*clamp( dot(p,q)/dot(q,q), 0.0, 1.0 );
    vec2 b = p - q*vec2( clamp( p.x/q.x, 0.0, 1.0 ), 1.0 );
    float s = -sign( q.y );
    vec2 d = min( vec2( dot(a,a), s*(p.x*q.y-p.y*q.x) ),
                  vec2( dot(b,b), s*(p.y-q.y)  ));
    return -sqrt(d.x)*sign(d.y);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec3 backgr = vec3(0.);
    vec3 col = vec3(1.);

    // Normalized pixel coordinates (from -1 to 1)
    vec2 uv = (2.0f * fragCoord - iResolution.xy) / iResolution.y;

    vec2 c2p = texelFetch(iChannel0, ivec2(1, 0), 0).xy;
    float a = texelFetch(iChannel0, ivec2(3, 0), 0).x;

    // SDF
    vec2 c2pos = uv;
    c2pos -= c2p;
    c2pos *= r2d(a);
    c2pos -= vec2(0., 0.09);
    float c2 = sdTriangle(c2pos, vec2(0.06, -0.18));

    // Output to screen
    if(c2 <= 0.)
    {
        fragColor = vec4(col, 1.);
    }
    else
    {
        fragColor = vec4(backgr,1.0);
    }
}

#define pi 3.1415926535

void save_at_ivec(in ivec2 desired_pos, in vec4 data, inout vec4 fragColor, in ivec2 current_pos)
{
    fragColor = (desired_pos.x==current_pos.x && desired_pos.y==current_pos.y ) ? data : fragColor;
}

float anglev(in vec2 a, in vec2 b)
{
    float theta = acos(dot(a / length(a), b / length(b)));
    return -mod(theta * sign(cross(vec3(a, 0.), vec3(b, 0.)).z), 2. * pi);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 c2p = texelFetch(iChannel0, ivec2(1, 0), 0).xy;
    vec2 fw = texelFetch(iChannel0, ivec2(2, 0), 0).xy;
    float angle = texelFetch(iChannel0, ivec2(3, 0), 0).x;


    fw = vec2(2. * cos(iTime), sin(iTime) * sin(iTime));

    angle = anglev(vec2(0., 1.), fw);
    c2p += fw * 0.3 * iTimeDelta;
    if (c2p.y > 1.2)
    {
        c2p.y *= -1.;
    }
    save_at_ivec(ivec2(1, 0), vec4(c2p, 0., 0.), fragColor, ivec2(fragCoord));
    save_at_ivec(ivec2(2, 0), vec4(fw, 0., 0.), fragColor, ivec2(fragCoord));
    save_at_ivec(ivec2(3, 0), vec4(angle, 0., 0., 0.), fragColor, ivec2(fragCoord));
}

mat2 r2d(float t)
{
    float sn = sin(t);
    float cs = cos(t);
    return mat2(cs, -sn, sn, cs);
}

